mapper.update:
UPDATE swm_safety_person_training
progress=#{progress}, complete_date=#{completeDate}, complete_status=#{completeStatus}, update_date=now()
WHERE id = #{id}

mapper.select:
SELECT fm.title, fm.push_date, fm.job_type, fm.type, sp.name as personName, a.* FROM swm_safety_person_training a JOIN swm_safety_file_manage fm ON a.safety_manage_id = fm.id JOIN swm_person sp ON a.identity_card = sp.identity_card
${sqlMap.where.toSql()}
AND sp.name LIKE concat('%',#{personName},'%')
AND fm.push_date = #{pushDateStr}
AND fm.title LIKE concat('%',#{title},'%')
ORDER BY ${sqlMap.order.toSql()}

SELECT fm.title, fm.push_date, fm.job_type, fm.type, fm.cover_url, fm.file_url, sp.name as personName, a.* FROM swm_safety_person_training a JOIN swm_safety_file_manage fm ON a.safety_manage_id = fm.id JOIN swm_person sp ON a.identity_card = sp.identity_card
${sqlMap.where.toSql()}
ORDER BY ${sqlMap.order.toSql()}
